package com.bank.threshold;

import java.util.*;
import java.util.logging.*;

public class ThresholdDemo {
    private static final Logger log = Logger.getLogger("Threshold");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Integer> amounts = List.of(5000, 500, 12000, 800, 20000);
        ThresholdService service = new ThresholdService();

        log.info(() -> "Above 1000 as text: " + service.aboveAsText(amounts, 1000));
    }
}

// ─── Would be in service/ThresholdService.java ───
class ThresholdService {
    List<String> aboveAsText(List<Integer> nums, int threshold) {
        return nums.stream()
            .filter(Objects::nonNull)                 // guard nulls
            .filter(n -> n > threshold)                // keep only above threshold FIRST
            .map(String::valueOf)                      // convert survivors to text
            .toList();
    }
}
